//! 跨域故事链 + 跨域事件链校验 (rgs-flash-mock)
//!
//! 闭环 `tools/rgs-flash-mock/README.md` 的两条已知缺口:
//! - #1 「gap_matrix 22 RPC stub 缺 E2E 故事链」
//! - #2 「saga_abstract 3 module 仅 mock, 缺 e2e cross-domain event verification」
//!
//! 设计要点 (3 条):
//! 1. 故事链 = 有序的跨域步骤, 每步绑定一个 `gap_matrix` 里的**真实 rpc_code** 与期望
//!    `RpcStatus`。实际状态取自 `GapMatrix::report().rpcs`, 不另造数据源。
//! 2. 跨域事件 = `(from_domain, event_name, to_domain)`。每个事件必须被下游某一步消费
//!    (无悬空事件), 消费必须发生在产生之后 (无顺序错乱), 且消费方必须是事件的
//!    `to_domain` (域归属一致)。
//! 3. 失败定位到**具体步骤**: 报告里同时给出失败步名 / rpc_code / 期望 vs 实际, 不是
//!    一个笼统的 bool。
//!
//! 真实业务语义 (k3s 真实域) 不在本地环境, 本模块只覆盖 mock 层的故事链与事件链一致性。

use crate::gap_matrix::{GapMatrix, RpcCategory, RpcStatus};
use std::collections::HashSet;

/// 跨域事件: 从一个域产生, 投递给另一个域。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CrossDomainEvent {
    pub from_domain: String,
    pub event_name: String,
    pub to_domain: String,
}

impl CrossDomainEvent {
    pub fn new(from_domain: &str, event_name: &str, to_domain: &str) -> Self {
        Self {
            from_domain: from_domain.to_string(),
            event_name: event_name.to_string(),
            to_domain: to_domain.to_string(),
        }
    }
}

/// 故事链的一步: 一个跨域 RPC + 期望状态 + 事件收发。
#[derive(Debug, Clone, PartialEq)]
pub struct StoryStep {
    /// 步骤名 (失败报告里用这个名字定位)
    pub name: String,
    /// 步骤所属域
    pub domain: String,
    /// `gap_matrix` 里的真实 rpc_code
    pub rpc_code: u32,
    /// rpc 名 (与 `gap_matrix` 的 `RpcRecord.name` 对齐)
    pub rpc_name: String,
    /// `gap_matrix` 里的 rpc 类别
    pub category: RpcCategory,
    /// 期望的 `RpcStatus`
    pub expected_status: RpcStatus,
    /// 本步产生的跨域事件
    pub emits: Vec<CrossDomainEvent>,
    /// 本步消费的事件名 (必须由**更早**的某一步产生)
    pub consumes: Vec<String>,
}

impl StoryStep {
    pub fn new(
        name: &str,
        domain: &str,
        rpc_code: u32,
        rpc_name: &str,
        category: RpcCategory,
        expected_status: RpcStatus,
    ) -> Self {
        Self {
            name: name.to_string(),
            domain: domain.to_string(),
            rpc_code,
            rpc_name: rpc_name.to_string(),
            category,
            expected_status,
            emits: Vec::new(),
            consumes: Vec::new(),
        }
    }

    pub fn emitting(mut self, event: CrossDomainEvent) -> Self {
        self.emits.push(event);
        self
    }

    pub fn consuming(mut self, event_name: &str) -> Self {
        self.consumes.push(event_name.to_string());
        self
    }
}

/// 单步的校验结果。
#[derive(Debug, Clone, PartialEq)]
pub enum StepOutcome {
    Pass,
    Failed { reason: String },
}

/// 单步结果。
#[derive(Debug, Clone, PartialEq)]
pub struct StepResult {
    pub step: String,
    pub domain: String,
    pub rpc_code: u32,
    pub outcome: StepOutcome,
}

impl StepResult {
    pub fn is_pass(&self) -> bool {
        matches!(self.outcome, StepOutcome::Pass)
    }
}

/// 整条故事链的校验报告。
#[derive(Debug, Clone, PartialEq)]
pub struct StoryChainReport {
    pub steps: Vec<StepResult>,
    pub passed: usize,
    pub failed: usize,
    /// 第一个失败步骤的描述 (失败定位)
    pub first_failure: Option<String>,
    /// 产生了但没有下游消费的事件
    pub dangling_events: Vec<String>,
    /// 消费顺序错乱的事件 (消费的��件由更后面的步骤产生)
    pub out_of_order_events: Vec<String>,
}

impl StoryChainReport {
    /// 全绿判定: 无失败步骤 + 无悬空事件 + 无顺序错乱。
    pub fn is_ok(&self) -> bool {
        self.failed == 0 && self.dangling_events.is_empty() && self.out_of_order_events.is_empty()
    }

    /// 失败步骤的 rpc_code 列表 (便于调用方精确定位到哪个 RPC)。
    pub fn failed_rpc_codes(&self) -> Vec<u32> {
        self.steps
            .iter()
            .filter(|s| !s.is_pass())
            .map(|s| s.rpc_code)
            .collect()
    }
}

/// 跨域故事链。
#[derive(Debug, Clone, PartialEq)]
pub struct StoryChain {
    pub steps: Vec<StoryStep>,
}

impl StoryChain {
    pub fn new(steps: Vec<StoryStep>) -> Self {
        Self { steps }
    }

    /// 默认的跨 5 域故事链 (player → economy → match → social → admin)。
    ///
    /// 每步的 rpc_code / 期望状态都取自 `gap_matrix` 的 22 个 stub:
    /// 201 GetPlayerProfile (Role/Partial)、602 CreateAuction (Econ/Pass)、
    /// 301 StartCombat (Combat/Pass)、702 SendMessage (Social/Partial)、
    /// 1101 BanAccount (Gm/Pass)。
    pub fn cross_domain_default() -> Self {
        let steps = vec![
            StoryStep::new(
                "player.session.open",
                "player",
                201,
                "GetPlayerProfile",
                RpcCategory::Role,
                RpcStatus::Partial,
            )
            .emitting(CrossDomainEvent::new(
                "player",
                "player.profile.loaded",
                "economy",
            )),
            StoryStep::new(
                "economy.reserve",
                "economy",
                602,
                "CreateAuction",
                RpcCategory::Econ,
                RpcStatus::Pass,
            )
            .consuming("player.profile.loaded")
            .emitting(CrossDomainEvent::new(
                "economy",
                "economy.reservation.confirmed",
                "match",
            )),
            StoryStep::new(
                "match.start",
                "match",
                301,
                "StartCombat",
                RpcCategory::Combat,
                RpcStatus::Pass,
            )
            .consuming("economy.reservation.confirmed")
            .emitting(CrossDomainEvent::new(
                "match",
                "match.combat.started",
                "social",
            )),
            StoryStep::new(
                "social.notify",
                "social",
                702,
                "SendMessage",
                RpcCategory::Social,
                RpcStatus::Partial,
            )
            .consuming("match.combat.started")
            .emitting(CrossDomainEvent::new(
                "social",
                "social.message.delivered",
                "admin",
            )),
            StoryStep::new(
                "admin.audit",
                "admin",
                1101,
                "BanAccount",
                RpcCategory::Gm,
                RpcStatus::Pass,
            )
            .consuming("social.message.delivered"),
        ];
        Self { steps }
    }

    /// 逐步核对 rpc 状态 + 校验事件链一致性。
    ///
    /// * 步骤失败: rpc_code 在 `gap_matrix` 里不存在, 或实际 `RpcStatus` 与期望不符
    /// * 悬空事件: 某步产生的事件没有任何下游步骤消费
    /// * 顺序错乱: 某步消费的事件由**更后面**的步骤产生
    /// * 域归属不符: 消费方域 != 事件的 `to_domain`
    pub fn verify(&self, matrix: &GapMatrix) -> StoryChainReport {
        let coverage = matrix.report();

        let mut results: Vec<StepResult> = Vec::with_capacity(self.steps.len());
        let mut passed = 0usize;
        let mut failed = 0usize;
        let mut first_failure: Option<String> = None;
        let mut dangling_events: Vec<String> = Vec::new();
        let mut out_of_order_events: Vec<String> = Vec::new();

        // 已产生的事件: (event_name, producing_step_index, to_domain)
        let mut emitted: Vec<(String, usize, String)> = Vec::new();
        let mut consumed: HashSet<String> = HashSet::new();

        for (idx, step) in self.steps.iter().enumerate() {
            // --- 事件消费检查 (消费必须来自更早的步骤) ---
            for event_name in &step.consumes {
                match emitted.iter().find(|(name, _, _)| name == event_name) {
                    Some((_, producer_idx, to_domain)) => {
                        consumed.insert(event_name.clone());
                        if *producer_idx >= idx {
                            out_of_order_events.push(format!(
                                "step '{}' 消费事件 '{}', 但该事件由 step '{}' (更靠后) 产生",
                                step.name,
                                event_name,
                                self.steps[*producer_idx].name
                            ));
                        }
                        if to_domain != &step.domain {
                            dangling_events.push(format!(
                                "step '{}' (域 {}) 消费事件 '{}' 的目标域是 {}, 域归属不符",
                                step.name, step.domain, event_name, to_domain
                            ));
                        }
                    }
                    None => {
                        if self
                            .steps
                            .iter()
                            .enumerate()
                            .any(|(j, s)| j > idx && s.emits.iter().any(|e| &e.event_name == event_name))
                        {
                            out_of_order_events.push(format!(
                                "step '{}' 消费事件 '{}', 但该事件由更后面的 step 产生",
                                step.name, event_name
                            ));
                        } else {
                            dangling_events.push(format!(
                                "step '{}' 消费事件 '{}', 但没有任何 step 产生该事件",
                                step.name, event_name
                            ));
                        }
                    }
                }
            }

            // --- rpc 状态核对 ---
            let outcome = match coverage.rpcs.iter().find(|r| r.code == step.rpc_code) {
                None => StepOutcome::Failed {
                    reason: format!(
                        "gap_matrix 无 rpc_code {} ({})",
                        step.rpc_code, step.rpc_name
                    ),
                },
                Some(rec) => {
                    if rec.name != step.rpc_name {
                        StepOutcome::Failed {
                            reason: format!(
                                "rpc {} 名称不符: 期望 '{}' 实际 '{}'",
                                step.rpc_code, step.rpc_name, rec.name
                            ),
                        }
                    } else if rec.status != step.expected_status {
                        StepOutcome::Failed {
                            reason: format!(
                                "rpc {} ({}) 期望状态 {} 实际 {}",
                                step.rpc_code,
                                step.rpc_name,
                                step.expected_status.as_str(),
                                rec.status.as_str()
                            ),
                        }
                    } else {
                        StepOutcome::Pass
                    }
                }
            };

            match &outcome {
                StepOutcome::Pass => passed += 1,
                StepOutcome::Failed { reason } => {
                    failed += 1;
                    if first_failure.is_none() {
                        first_failure = Some(format!("step '{}' (rpc {}) 失败: {}", step.name, step.rpc_code, reason));
                    }
                }
            }

            results.push(StepResult {
                step: step.name.clone(),
                domain: step.domain.clone(),
                rpc_code: step.rpc_code,
                outcome,
            });

            // --- 本步产生的事件 ---
            for event in &step.emits {
                emitted.push((
                    event.event_name.clone(),
                    idx,
                    event.to_domain.clone(),
                ));
            }
        }

        // --- 悬空事件: 产生了但没人消费 ---
        for (event_name, producer_idx, _) in &emitted {
            if !consumed.contains(event_name) {
                dangling_events.push(format!(
                    "step '{}' 产生的事件 '{}' 没有下游消费",
                    self.steps[*producer_idx].name, event_name
                ));
            }
        }

        StoryChainReport {
            steps: results,
            passed,
            failed,
            first_failure,
            dangling_events,
            out_of_order_events,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_chain_covers_five_domains() {
        let chain = StoryChain::cross_domain_default();
        assert_eq!(chain.steps.len(), 5);
        let mut domains: Vec<&str> = chain.steps.iter().map(|s| s.domain.as_str()).collect();
        domains.sort_unstable();
        domains.dedup();
        assert_eq!(domains.len(), 5, "默认故事链应覆盖 5 个域");
    }

    #[test]
    fn default_chain_event_names_are_unique() {
        let chain = StoryChain::cross_domain_default();
        let mut names: Vec<&str> = chain
            .steps
            .iter()
            .flat_map(|s| s.emits.iter().map(|e| e.event_name.as_str()))
            .collect();
        let total = names.len();
        names.sort_unstable();
        names.dedup();
        assert_eq!(names.len(), total, "事件名不应重复");
    }

    #[test]
    fn default_chain_verifies_green_against_gap_matrix() {
        let report = StoryChain::cross_domain_default().verify(&GapMatrix::new());
        assert!(report.is_ok(), "默认故事链应全绿: {:?}", report);
        assert_eq!(report.failed, 0);
        assert!(report.dangling_events.is_empty());
        assert!(report.out_of_order_events.is_empty());
    }

    #[test]
    fn event_target_domain_must_match_consumer_domain() {
        let chain = StoryChain::new(vec![
            StoryStep::new(
                "a",
                "player",
                201,
                "GetPlayerProfile",
                RpcCategory::Role,
                RpcStatus::Partial,
            )
            .emitting(CrossDomainEvent::new("player", "evt", "economy")),
            StoryStep::new(
                "b",
                "match",
                301,
                "StartCombat",
                RpcCategory::Combat,
                RpcStatus::Pass,
            )
            .consuming("evt"),
        ]);
        let report = chain.verify(&GapMatrix::new());
        assert!(
            !report.dangling_events.is_empty(),
            "消费方域与事件目标域不符应被检出"
        );
    }
}
